<script setup>
import {computed,ref} from 'vue';
import {size} from '../lib/catalog';
const props=defineProps({files:Array,previewFile:Object,disabled:Boolean});const emit=defineEmits(['add','remove']);const dragging=ref(false),expanded=ref(false);
const isImage=f=>/\.(png|jpe?g|webp|gif|bmp|avif)$/i.test(f.name);
const images=computed(()=>props.files.filter(isImage)),others=computed(()=>props.files.filter(f=>!isImage(f)));
const cover=f=>props.previewFile===f;
const type=f=>/\.unitypackage$/i.test(f.name)?'UNITY':/\.(zip|rar|7z)$/i.test(f.name)?'ZIP':'FILE';
function drop(e){dragging.value=false;if(!props.disabled)emit('add',[...e.dataTransfer.files]);}
</script>
<template><div class="compact-file-drop" :class="{dragging}" @dragover.prevent="!disabled&&(dragging=true)" @dragleave.self="dragging=false" @drop.prevent="drop"><div v-for="file in others" :key="file.name" class="compact-file-row"><span class="compact-file-type" :class="type(file).toLowerCase()">{{type(file)}}</span><span class="compact-file-name" :title="file.name">{{file.name}}</span><small>{{size(file.size)}}</small><button type="button" class="compact-file-remove" :disabled="disabled" :aria-label="'Quitar '+file.name" @click="emit('remove',file)">×</button></div><div v-if="images.length" class="compact-file-row"><span class="compact-file-type img">IMG</span><button type="button" class="compact-image-group" :aria-expanded="expanded" @click="expanded=!expanded">{{images.length===1?images[0].name:images.length+' imágenes'}}<span v-if="images.some(cover)" class="compact-cover-mark"> ★ portada</span></button><small>{{size(images.reduce((n,f)=>n+f.size,0))}}</small><button v-if="images.length===1" class="compact-file-remove" type="button" :disabled="disabled" aria-label="Quitar imagen" @click="emit('remove',images[0])">×</button></div><template v-if="expanded&&images.length>1"><div v-for="file in images" :key="file.name" class="compact-file-row compact-image-child"><span class="compact-file-name">{{file.name}}<span v-if="cover(file)" class="compact-cover-mark"> ★ portada</span></span><small>{{size(file.size)}}</small><button type="button" class="compact-file-remove" :disabled="disabled" :aria-label="'Quitar '+file.name" @click="emit('remove',file)">×</button></div></template><p>{{files.length?'Soltá más archivos acá':'Soltá los archivos acá o presioná + Elegir'}}</p></div></template>